import type { SqlValue } from "./runtime.ts";

/*
 * A small query model shared by adapters that cannot hand the runtime SQL of
 * their own. It covers single-table reads and writes with a few comparisons,
 * and an insert that updates the row it collides with; anything richer should
 * arrive as SQL generated by the ORM.
 *
 * Values are bound as given: they are stored values. An adapter that receives
 * values from outside converts them with the column codec (column-codec.ts)
 * first.
 */

/**
 * - `eq`: equal; with `null`, the column is null.
 * - `neq`: not equal; with `null`, the column is not null. As in SQL, a
 *   column that is null is neither equal nor unequal to a value.
 * - `gt`, `gte`: greater than; greater than or equal.
 * - `lt`, `lte`: less than; less than or equal.
 * - `like`: SQLite's LIKE, with `%` and `_` as its wildcards and `\` before
 *   one that is meant as itself.
 *
 * Comparisons are SQLite's: by the column's affinity, text by its bytes.
 */
export type ComparisonOperator = "eq" | "neq" | "gt" | "gte" | "lt" | "lte" | "like";

export interface Condition {
  column: string;
  op: ComparisonOperator;
  /** `null` matches rows where the column is null (`eq`) or is not (`neq`); no other comparison takes it. */
  value: SqlValue;
}

const OPERATORS: Record<ComparisonOperator, string> = { eq: "=", neq: "<>", gt: ">", gte: ">=", lt: "<", lte: "<=", like: "LIKE" };

export type Query =
  | {
      kind: "select";
      table: string;
      /** Default: every column. */
      columns?: string[];
      where?: Condition[];
      orderBy?: { column: string; direction: "asc" | "desc" }[];
      limit?: number;
      offset?: number;
    }
  | { kind: "count"; table: string; where?: Condition[] }
  | { kind: "insert"; table: string; values: Record<string, SqlValue> }
  | { kind: "update"; table: string; set: Record<string, SqlValue>; where?: Condition[] }
  | { kind: "delete"; table: string; where?: Condition[] }
  | {
      /**
       * Inserts rows; a row whose `conflict` columns equal those of an
       * existing row updates that row instead (`update`, the default) or is
       * left out (`ignore`). On update, every given column that is not a
       * conflict column is set. `conflict` names a primary key or another
       * unique key of the table; a conflict column that the rows do not give
       * takes its default. Every row gives the same columns.
       */
      kind: "upsert";
      table: string;
      rows: Record<string, SqlValue>[];
      conflict: string[];
      action?: "update" | "ignore";
    };

export interface CompiledQuery {
  sql: string;
  parameters: SqlValue[];
}

/** Quotes an identifier for SQLite. */
export function quoteIdentifier(name: string): string {
  return `"${name.replaceAll('"', '""')}"`;
}

function whereClause(conditions: Condition[] | undefined, parameters: SqlValue[]): string {
  if (conditions === undefined || conditions.length === 0) {
    return "";
  }
  const terms = conditions.map((condition) => {
    const operator = Object.hasOwn(OPERATORS, condition.op) ? OPERATORS[condition.op] : undefined;
    if (operator === undefined) {
      throw new TypeError(`Unknown comparison "${String(condition.op)}"; expected one of ${Object.keys(OPERATORS).join(", ")}.`);
    }
    if (condition.value === null || condition.value === undefined) {
      if (condition.op !== "eq" && condition.op !== "neq") {
        throw new TypeError(`"${condition.op}" cannot compare "${condition.column}" with null; only "eq" and "neq" can.`);
      }
      return `${quoteIdentifier(condition.column)} IS ${condition.op === "eq" ? "" : "NOT "}NULL`;
    }
    parameters.push(condition.value);
    // A backslash before a wildcard makes it the character itself.
    return `${quoteIdentifier(condition.column)} ${operator} ?${condition.op === "like" ? " ESCAPE '\\'" : ""}`;
  });
  return ` WHERE ${terms.join(" AND ")}`;
}

function count(value: number | undefined, what: string): number | undefined {
  if (value !== undefined && (!Number.isInteger(value) || value < 0)) {
    throw new TypeError(`${what} must be a non-negative integer.`);
  }
  return value;
}

/** Compiles a query to SQLite SQL with positional parameters. */
export function compileQuery(query: Query): CompiledQuery {
  const parameters: SqlValue[] = [];
  const table = quoteIdentifier(query.table);
  switch (query.kind) {
    case "select": {
      const columns = query.columns === undefined ? "*" : query.columns.map(quoteIdentifier).join(", ");
      let sql = `SELECT ${columns} FROM ${table}${whereClause(query.where, parameters)}`;
      if (query.orderBy !== undefined && query.orderBy.length > 0) {
        sql += ` ORDER BY ${query.orderBy.map((entry) => `${quoteIdentifier(entry.column)} ${entry.direction === "desc" ? "DESC" : "ASC"}`).join(", ")}`;
      }
      const limit = count(query.limit, "limit");
      const offset = count(query.offset, "offset");
      if (limit !== undefined || offset !== undefined) {
        // SQLite needs a LIMIT to accept an OFFSET; -1 means no limit.
        sql += ` LIMIT ${limit ?? -1}`;
        if (offset !== undefined) {
          sql += ` OFFSET ${offset}`;
        }
      }
      return { sql, parameters };
    }
    case "count":
      return { sql: `SELECT COUNT(*) AS "count" FROM ${table}${whereClause(query.where, parameters)}`, parameters };
    case "insert": {
      const names = Object.keys(query.values);
      if (names.length === 0) {
        return { sql: `INSERT INTO ${table} DEFAULT VALUES`, parameters };
      }
      parameters.push(...names.map((name) => query.values[name]));
      return { sql: `INSERT INTO ${table} (${names.map(quoteIdentifier).join(", ")}) VALUES (${names.map(() => "?").join(", ")})`, parameters };
    }
    case "update": {
      const names = Object.keys(query.set);
      if (names.length === 0) {
        throw new TypeError("An update needs at least one column to set.");
      }
      parameters.push(...names.map((name) => query.set[name]));
      return { sql: `UPDATE ${table} SET ${names.map((name) => `${quoteIdentifier(name)} = ?`).join(", ")}${whereClause(query.where, parameters)}`, parameters };
    }
    case "delete":
      return { sql: `DELETE FROM ${table}${whereClause(query.where, parameters)}`, parameters };
    case "upsert": {
      const [first] = query.rows;
      if (first === undefined) {
        throw new TypeError("An upsert needs at least one row.");
      }
      const names = Object.keys(first);
      if (names.length === 0) {
        throw new TypeError("An upsert needs at least one column.");
      }
      if (query.conflict.length === 0) {
        throw new TypeError("An upsert needs the columns of the key that a row may collide on.");
      }
      const rows = query.rows.map((row, index) => {
        const keys = Object.keys(row);
        if (keys.length !== names.length || keys.some((name) => !names.includes(name))) {
          throw new TypeError(`Row ${index + 1} of the upsert gives the columns ${keys.join(", ")}; every row gives ${names.join(", ")}.`);
        }
        parameters.push(...names.map((name) => row[name]));
        return `(${names.map(() => "?").join(", ")})`;
      });
      const updated = names.filter((name) => !query.conflict.includes(name));
      const action =
        query.action === "ignore" || updated.length === 0
          ? "DO NOTHING"
          : `DO UPDATE SET ${updated.map((name) => `${quoteIdentifier(name)} = excluded.${quoteIdentifier(name)}`).join(", ")}`;
      return {
        sql: `INSERT INTO ${table} (${names.map(quoteIdentifier).join(", ")}) VALUES ${rows.join(", ")} ON CONFLICT (${query.conflict.map(quoteIdentifier).join(", ")}) ${action}`,
        parameters,
      };
    }
  }
}
